import * as yup from 'yup';
const tf = fn => value => typeof value === 'string' ? fn(value) : value;
const schema = yup.object({
  name: yup.string().label('名前').transform(tf(value => value.normalize('NFKC') //Unicode正規化、英数字などを全角→半角、カナを半角→全角などの正規化
  .replace(/\s+/g, ' ') //\s(全角・半角スペースや改行)+(1回以上の繰り返し)g(全ての一致箇所を取得)、連続スペースを1個にする(姓 名の見栄え安定)
  .trim())).required('${label}は必須入力です。').max(20, '${label}は${max}文字以内で入力してください。'),
  email: yup.string().label('メールアドレス').transform(tf(v => v.normalize('NFKC').trim().toLowerCase() //小文字統一が楽
  )).required('${label}は必須入力です。').email('${label}の形式が不正です。'),
  title: yup.string().label('件名').required('${label}は必須入力です。').max(50, '${label}は${min}文字以上で入力してください。'),
  message: yup.string().label('本文').required('${label}は必須入力です。').min(10, '${label}は${min}文字以上で入力してください。')
});
export default schema;
